        //save to blob
        AzureBlobHelper.WriteFileToBlob("documents", $"{uniquFolder}/{filename}", fileData);

        var taskId = Convert.ToInt32(httpRequest.Params["TaskId"]);
        Tasks().First(e => e.Id == taskId); //security, throw unwanted ids (not mine)

        //save to DB
        _db.Context.Attachments.Add(new Attachment
        {
            ParentId = taskId,
            FileName = filename,
            URL = $"https://lshusersdata.blob.core.windows.net/documents/{uniquFolder}/{filename}",
            Size = fileData.Length
        });
        _db.Context.SaveChanges();

        result = Request.CreateResponse(HttpStatusCode.Created, 1);
    }
    else
    {
        result = Request.CreateResponse(HttpStatusCode.BadRequest,1);
    }

    return result;

